INSERT INTO library_questions (owner_key, collection_id, position, collection_title, question, search_text, updated_at) VALUES
  ('', 'mencius', 0, '《得道多助，失道寡助》', '["本文开头提出了怎样的观点？",["天时比地利重要，地利比人和重要","天时不如地利，地利不如人和","有地利便一定能够取胜","战争的胜负只取决于兵器"],1,"首句层层比较天时、地利与人和，确立了人和最重要的观点。",20]', '《得道多助,失道寡助》 孟子 文言文 本文开头提出了怎样的观点? 天时比地利重要,地利比人和重要 天时不如地利,地利不如人和 有地利便一定能够取胜 战争的胜负只取决于兵器 首句层层比较天时、地利与人和,确立了人和最重要的观点。', 0),
  ('', 'mencius', 1, '《得道多助，失道寡助》', '["“三里之城，七里之郭”中的“郭”指什么？",["护城河","内城的城墙","外城","驻军的营地"],2,"古代城邑往往有内外两重城墙，内为城，外为郭。",20]', '《得道多助,失道寡助》 孟子 文言文 “三里之城,七里之郭”中的“郭”指什么? 护城河 内城的城墙 外城 驻军的营地 古代城邑往往有内外两重城墙,内为城,外为郭。', 0),
  ('', 'mencius', 2, '《得道多助，失道寡助》', '["“环而攻之而不胜”的例子说明了什么？",["即使占有天时，也可能因对方占有地利而不能取胜","只要围城，攻方就一定能取胜","防守一方的胜利完全依靠人和","城墙低矮是进攻失败的原因"],0,"文中指出围攻的一方必有得天时的机会，却仍未取胜，借此说明天时不如地利。",30]', '《得道多助,失道寡助》 孟子 文言文 “环而攻之而不胜”的例子说明了什么? 即使占有天时,也可能因对方占有地利而不能取胜 只要围城,攻方就一定能取胜 防守一方的胜利完全依靠人和 城墙低矮是进攻失败的原因 文中指出围攻的一方必有得天时的机会,却仍未取胜,借此说明天时不如地利。', 0),
  ('', 'mencius', 3, '《得道多助，失道寡助》', '["“城非不高也，池非不深也”中的“池”指什么？",["水井","城内的池塘","湖泊","护城河"],3,"这里的“池”是城墙外用来防守的护城河。",20]', '《得道多助,失道寡助》 孟子 文言文 “城非不高也,池非不深也”中的“池”指什么? 水井 城内的池塘 湖泊 护城河 这里的“池”是城墙外用来防守的护城河。', 0),
  ('', 'mencius', 4, '《得道多助，失道寡助》', '["下列对“兵革非不坚利也，米粟非不多也”的理解，哪一项正确？",["士兵不强壮，粮食也不足","武器和甲胄并非不坚固锋利，粮食也并非不充足","士兵虽多，却缺少锋利的武器","兵器锋利，但战事已经耗尽粮食"],1,"“兵革”指武器和甲胄，“米粟”泛指粮食。多个双重否定强调守城条件充足。",30]', '《得道多助,失道寡助》 孟子 文言文 下列对“兵革非不坚利也,米粟非不多也”的理解,哪一项正确? 士兵不强壮,粮食也不足 武器和甲胄并非不坚固锋利,粮食也并非不充足 士兵虽多,却缺少锋利的武器 兵器锋利,但战事已经耗尽粮食 “兵革”指武器和甲胄,“米粟”泛指粮食。多个双重否定强调守城条件充足。', 0),
  ('', 'mencius', 5, '《得道多助，失道寡助》', '["“委而去之”的意思是什么？",["接受委任，前往守城","命令士兵留在城中","放弃城池，离开那里","把城池交给盟友防守"],2,"“委”是放弃，“去”是离开。这里指守城者弃城而逃。",20]', '《得道多助,失道寡助》 孟子 文言文 “委而去之”的意思是什么? 接受委任,前往守城 命令士兵留在城中 放弃城池,离开那里 把城池交给盟友防守 “委”是放弃,“去”是离开。这里指守城者弃城而逃。', 0),
  ('', 'mencius', 6, '《得道多助，失道寡助》', '["城防坚固、武器精良、粮食充足，却仍然“委而去之”。作者借此说明什么？",["地利不如人和","天时足以弥补地利的不足","坚固的城墙会削弱战斗力","只要粮食充足就能守城"],0,"守方拥有多种有利条件却弃城，突出团结和支持比地利更重要。",25]', '《得道多助,失道寡助》 孟子 文言文 城防坚固、武器精良、粮食充足,却仍然“委而去之”。作者借此说明什么? 地利不如人和 天时足以弥补地利的不足 坚固的城墙会削弱战斗力 只要粮食充足就能守城 守方拥有多种有利条件却弃城,突出团结和支持比地利更重要。', 0),
  ('', 'mencius', 7, '《得道多助，失道寡助》', '["“域民不以封疆之界”的意思最接近哪一项？",["治理民众必须先扩张疆土","防御敌人完全依靠边界","民众只能住在边界附近","使百姓安居，不能只靠划定疆界"],3,"这句话与“固国”“威天下”并列，指出疆界等外在条件不能代替人心的支持。",30]', '《得道多助,失道寡助》 孟子 文言文 “域民不以封疆之界”的意思最接近哪一项? 治理民众必须先扩张疆土 防御敌人完全依靠边界 民众只能住在边界附近 使百姓安居,不能只靠划定疆界 这句话与“固国”“威天下”并列,指出疆界等外在条件不能代替人心的支持。', 0),
  ('', 'mencius', 8, '《得道多助，失道寡助》', '["“域民不以……，固国不以……，威天下不以……”主要运用了哪种表达方式？",["比喻","排比","反问","夸张"],1,"三个结构相近的句子并列，从安民、固国到威天下，增强了论证的气势。",20]', '《得道多助,失道寡助》 孟子 文言文 “域民不以......,固国不以......,威天下不以......”主要运用了哪种表达方式? 比喻 排比 反问 夸张 三个结构相近的句子并列,从安民、固国到威天下,增强了论证的气势。', 0),
  ('', 'mencius', 9, '《得道多助，失道寡助》', '["文中“得道者多助”的“道”主要指什么？",["行军时选择的道路","修身时学习的知识","合乎道义的政治主张与做法","运用兵器的技巧"],2,"“得道”指施行合乎道义、能赢得人心的政治，不能理解为得到一条道路。",25]', '《得道多助,失道寡助》 孟子 文言文 文中“得道者多助”的“道”主要指什么? 行军时选择的道路 修身时学习的知识 合乎道义的政治主张与做法 运用兵器的技巧 “得道”指施行合乎道义、能赢得人心的政治,不能理解为得到一条道路。', 0),
  ('', 'mencius', 10, '《得道多助，失道寡助》', '["“亲戚畔之”的“畔”在这里是什么意思？",["背叛","靠近","赞同","等待"],0,"“畔”同“叛”，这里指亲属也背离失道的人。",20]', '《得道多助,失道寡助》 孟子 文言文 “亲戚畔之”的“畔”在这里是什么意思? 背叛 靠近 赞同 等待 “畔”同“叛”,这里指亲属也背离失道的人。', 0),
  ('', 'mencius', 11, '《得道多助，失道寡助》', '["“寡助之至，亲戚畔之；多助之至，天下顺之”写出了怎样的对比？",["山川险要与兵器锋利的对比","进攻一方与守城一方地形的对比","得天时与失天时的对比","失道者众叛亲离与得道者获得广泛支持的对比"],3,"作者把支持极少和支持极多的结果并列，具体说明得道与失道的不同后果。",25]', '《得道多助,失道寡助》 孟子 文言文 “寡助之至,亲戚畔之;多助之至,天下顺之”写出了怎样的对比? 山川险要与兵器锋利的对比 进攻一方与守城一方地形的对比 得天时与失天时的对比 失道者众叛亲离与得道者获得广泛支持的对比 作者把支持极少和支持极多的结果并列,具体说明得道与失道的不同后果。', 0),
  ('', 'mencius', 12, '《得道多助，失道寡助》', '["“故君子有不战，战必胜矣”中的“战必胜”依据是什么？",["得道者必有比对手更坚固的城池","得道者得到天下人的支持，而失道者连亲属也背离","君子总能挑选最有利的天气","得道者可以靠兵器威服天下"],1,"结尾紧承“以天下之所顺，攻亲戚之所畔”，以人心向背说明取胜的依据。",30]', '《得道多助,失道寡助》 孟子 文言文 “故君子有不战,战必胜矣”中的“战必胜”依据是什么? 得道者必有比对手更坚固的城池 得道者得到天下人的支持,而失道者连亲属也背离 君子总能挑选最有利的天气 得道者可以靠兵器威服天下 结尾紧承“以天下之所顺,攻亲戚之所畔”,以人心向背说明取胜的依据。', 0),
  ('', 'mencius', 13, '《得道多助，失道寡助》', '["下列哪一项最准确地概括了本文的论证思路？",["先叙述历史事件，再介绍守城方法","先论述治国之道，再总结地形的重要性","先提出人和最重要，再用攻守实例论证，最后推及治国与得道","先比较兵器和粮食，再主张凡事都不应交战"],2,"文章从天时、地利、人和的比较出发，用攻守实例论证，再把人和推及施政与人心向背。",35]', '《得道多助,失道寡助》 孟子 文言文 下列哪一项最准确地概括了本文的论证思路? 先叙述历史事件,再介绍守城方法 先论述治国之道,再总结地形的重要性 先提出人和最重要,再用攻守实例论证,最后推及治国与得道 先比较兵器和粮食,再主张凡事都不应交战 文章从天时、地利、人和的比较出发,用攻守实例论证,再把人和推及施政与人心向背。', 0);
